const data = $input.item.json;

const pilotLeadId = data.pilot_lead_id ? `'${data.pilot_lead_id}'` : 'NULL';
const pilotResponse = (data.pilot_response || '').replace(/'/g, "''");

return {
  json: {
    query: `UPDATE meli_leads SET status = '${data.new_status}', pilot_lead_id = ${pilotLeadId}, sf_response = '${pilotResponse}' WHERE id = '${data.lead_id}'`
  }
};

const body = $input.item.json.body;
const { tel_sufijo, updates } = body;

if (!tel_sufijo || !updates || Object.keys(updates).length === 0) {
  throw new Error('Faltan parámetros');
}

const { publicacion_id, ...updatesFiltradas } = updates;

if (Object.keys(updatesFiltradas).length === 0) {
  throw new Error('No hay campos válidos para actualizar');
}

const setClauses = Object.entries(updatesFiltradas)
  .map(([key, value]) => {
    if (typeof value === 'number') return `${key} = ${value}`;
    return `${key} = '${String(value).replace(/'/g, "''")}'`;
  })
  .join(', ');

return {
  json: {
    query: `UPDATE meli_leads SET ${setClauses} WHERE RIGHT(REGEXP_REPLACE(buyer_phone, '[^0-9]', ''), 8) = '${tel_sufijo}' AND status IN ('active', 'sent')`
  }
};

const lead = $('🔀 Resolver Asesor/Marca').item.json;

const CONTACT_TYPE_ID = 1;

const appkeyByMarca = {
  'BAIC': 'A4016CE4-585B-4204-8043-86CA125EF352',
  'FIAT': '0B709CC7-83F0-43C1-A541-9D78B829CDB1',
  'PEUGEOT': '0B709CC7-83F0-43C1-A541-9D78B829CDB1',
  'CITROEN': '0B709CC7-83F0-43C1-A541-9D78B829CDB1',
  'DS': '0B709CC7-83F0-43C1-A541-9D78B829CDB1',
  'USADOS': '0B709CC7-83F0-43C1-A541-9D78B829CDB1',
};

const baiccentral_id = 2910875794;
const baiclong_ids = [310104776, 3328612086];
const autofrance_ids = [255619706, 192973256, 2432747166, 2569671813, 1997834029, 255619619, 188299312, 296583736, 296583094, 3396636159, 296585502, 2036674383, 3318954106, 3468075382, 3317595043];

const appkey = (lead.marca_detectada === 'BAIC') ? 'A4016CE4-585B-4204-8043-86CA125EF352' :
               autofrance_ids.includes(lead.user_id) ? '0B709CC7-83F0-43C1-A541-9D78B829CDB1' :
               baiclong_ids.includes(lead.user_id) ? 'A4016CE4-585B-4204-8043-86CA125EF352' :
               lead.user_id === baiccentral_id ? 'A4016CE4-585B-4204-8043-86CA125EF352' : null;
if (!appkey) {
  console.warn(`No hay appkey para la marca: ${lead.marca_detectada}`);
  return [];
}

const canonicalModels = [
  // BAIC
  { keys: ['x55 ii hybrid', 'x55ii hybrid'], name: 'X55 II Hybrid' },
  { keys: ['x55 ii', 'x55ii'], name: 'X55 II' },
  { keys: ['x35'], name: 'X35' },
  { keys: ['bj30e', 'bj 30e'], name: 'BJ30E' },
  { keys: ['bj40', 'bj 40'], name: 'BJ40' },
  { keys: ['bj60', 'bj 60'], name: 'BJ60' },
  { keys: ['eu5'], name: 'EU5' },
  { keys: ['u5'], name: 'U5' },
  // FIAT
  { keys: ['ducato'], name: 'Ducato' },
  { keys: ['cronos'], name: 'Cronos' },
  { keys: ['pulse'], name: 'Pulse' },
  { keys: ['fastback'], name: 'Fastback' },
  { keys: ['toro'], name: 'Toro' },
  { keys: ['scudo'], name: 'Scudo' },
  { keys: ['mobi'], name: 'Mobi' },
  { keys: ['argo'], name: 'Argo' },
  { keys: ['fiorino'], name: 'Fiorino' },
  // PEUGEOT
  { keys: ['e-208'], name: 'e-208' },
  { keys: ['e-2008'], name: 'e-2008' },
  { keys: ['2008'], name: '2008' },
  { keys: ['3008'], name: '3008' },
  { keys: ['5008'], name: '5008' },
  { keys: ['208'], name: '208' },
  { keys: ['308'], name: '308' },
  { keys: ['408'], name: '408' },
  { keys: ['partner'], name: 'Partner' },
  { keys: ['expert'], name: 'Expert' },
  { keys: ['landtrek'], name: 'Landtrek' },
  // CITROEN
  { keys: ['berlingo'], name: 'Berlingo' },
  { keys: ['basalt'], name: 'Basalt' },
  { keys: ['c-elysee', 'c elysee'], name: 'C-Elysee' },
  { keys: ['c3 aircross', 'c3aircross'], name: 'C3 Aircross' },
  { keys: ['c3'], name: 'C3' },
  { keys: ['c4 cactus', 'c4cactus'], name: 'C4 Cactus' },
  { keys: ['c4'], name: 'C4' },
  { keys: ['c5'], name: 'C5' },
  { keys: ['jumpy'], name: 'Jumpy' },
  { keys: ['jumper'], name: 'Jumper' },
  { keys: ['dispatch'], name: 'Dispatch' },
  { keys: ['spacetourer'], name: 'Spacetourer' },
  // DS
  { keys: ['ds3'], name: 'DS3' },
  { keys: ['ds4'], name: 'DS4' },
  { keys: ['ds7'], name: 'DS7' },
  { keys: ['ds9'], name: 'DS9' },
];

const resolveModelo = (tituloOriginal) => {
  const tituloLower = (tituloOriginal || '').toLowerCase();
  for (const model of canonicalModels) {
    if (model.keys.some(key => tituloLower.includes(key))) {
      return model.name;
    }
  }
  return (tituloOriginal || '').replace(/\s*asesor\s+.+$/i, '').trim();
};

const name = (lead.buyer_nombre || '').trim();
const cellphone = (lead.buyer_phone || '').replace(/\D/g, '');
const email = lead.buyer_email || '';
const modelo = resolveModelo(lead.item_titulo);
const notes = `Publicación: ${lead.item_id} | Precio: ${lead.item_precio} | Link: ${lead.item_permalink || ''} | Asesor: ${lead.asesor_nombre_match || ''} | Teléfono asesor: ${lead.asesor_phone || ''}`;

const contactParams = cellphone
  ? `&pilot_cellphone=${encodeURIComponent(cellphone)}`
  : `&pilot_email=${encodeURIComponent(email)}`;

// Sin asesor (Baic Central): no se manda pilot_assigned_user y el lead queda sin asignar en el grupo de captura
const assignParams = (lead.pilot_assigned_user ? `&pilot_assigned_user=${encodeURIComponent(lead.pilot_assigned_user)}` : '') +
  (lead.pilot_capture_group ? `&pilot_provider_service=${encodeURIComponent(lead.pilot_capture_group)}` : '');

const url = `https://api.pilotsolution.net/webhooks/welcome.php?action=create&appkey=${appkey}&pilot_firstname=${encodeURIComponent(name)}&pilot_contact_type_id=${CONTACT_TYPE_ID}&pilot_business_type_id=${lead.pilot_business_type_id}${contactParams}&pilot_notes=${encodeURIComponent(notes)}&pilot_suborigin_id=${lead.pilot_origin}&pilot_product_of_interest=${encodeURIComponent(modelo)}${assignParams}`;

return {
  json: {
    lead_id: lead.id,
    user_id: lead.user_id,
    destino: lead.destino,
    url,
    modelo_resuelto: modelo,
    pilot_origin: lead.pilot_origin,
    pilot_business_type_id: lead.pilot_business_type_id,
    pilot_assigned_user: lead.pilot_assigned_user,
    pilot_capture_group: lead.pilot_capture_group || null,
    asesor_fuente: lead.asesor_fuente || null,
    marca_detectada: lead.marca_detectada,
    appkey
  }
};

const lead = $input.item.json;
const normalizarTel = (tel) => {
  if (!tel) return null;
  const digits = tel.toString().replace(/\D/g, '');
  return digits.slice(-8);
};
const normalizarBuyerPhone = (tel) => {
  if (!tel) return null;
  let digits = tel.toString().replace(/\D/g, '');
  if (digits.startsWith('549')) return '+' + digits;
  if (digits.startsWith('54')) return '+549' + digits.slice(2);
  if (digits.startsWith('9') && digits.length >= 10) return '+54' + digits;
  return '+549' + digits;
};
const sufijo1 = normalizarTel(lead.asesor_phone);
const sufijo2 = normalizarTel(lead.asesor_phone2);
return {
  json: {
    ...lead,
    buyer_phone: normalizarBuyerPhone(lead.buyer_phone),
    asesor_sufijo1: sufijo1 || '',
    asesor_sufijo2: sufijo2 || ''
  }
};

const lead = $('Normalizar teléfonos').item.json;
const asesores = $('🗄️ Buscar asesor').all().filter(a => a.json && a.json.email);

const getLast8 = (phone) => (phone || '').toString().replace(/\D/g, '').slice(-8);

const BAIC_CENTRAL = 2910875794;
// Baic Central: asesores del grupo "Ventas ML" (834) de la suite; el cliente lo mantiene ahí.
// Sin asesor -> va sin asignar al grupo de captura de MercadoLibre, para no perder el lead.
const BAIC_CENTRAL_GRUPO_CAPTURA = 'GC - VN BAIC MERCADOLIBRE 3';
const usuariosSuite = (() => {
  try { return $('obtenerAsesoresBaicCentral').first().json?.data?.users || []; }
  catch (e) { return []; }
})();
const sufijos = [lead.asesor_sufijo1, lead.asesor_sufijo2].filter(s => s && s.length === 8);
const asesorSuite = usuariosSuite.find(u => u.status === 'active' && u.email && sufijos.includes(getLast8(u.phone)));

const determineMarca = (lead) => {
  const texto = (lead.item_titulo || '').toLowerCase();
  if (texto.includes('baic') || texto.includes('arcfox')) return 'BAIC';
  if (texto.includes('fiat') || texto.includes('ducato') || texto.includes('cronos') || texto.includes('pulse') || texto.includes('fastback') || texto.includes('toro') || texto.includes('scudo') || texto.includes('mobi') || texto.includes('argo') || texto.includes('fiorino')) return 'FIAT';
  if (texto.includes('peugeot') || texto.includes('3008') || texto.includes('2008') || texto.includes('5008') || texto.includes('308') || texto.includes('408') || texto.includes('208') || texto.includes('partner') || texto.includes('expert') || texto.includes('landtrek')) return 'PEUGEOT';
if (texto.includes('citroen') || texto.includes('citroën') || texto.includes('berlingo') || texto.includes('basalt') || texto.includes('aircross') || texto.includes('c3') || texto.includes('c4') || texto.includes('c5') || texto.includes('jumpy') || texto.includes('jumper') || texto.includes('dispatch') || texto.includes('c-elysee') || texto.includes('spacetourer')) return 'CITROEN';
  if (texto.includes(' ds ') || texto.startsWith('ds ') || texto.includes('ds3') || texto.includes('ds4') || texto.includes('ds7') || texto.includes('ds9')) return 'DS';
  return null;
};

const getOrigin = (marca, tipo) => {
  const origins = {
    'FIAT':    { VN: 'G7UGU65Z3IEOEYC6C', PDA: 'G7UGVHHWLC99QB0Q9' },
    'PEUGEOT': { VN: 'G7WFK23Z7I4SNYZNK', PDA: 'G7WFI1LGYY05VI40C' },
    'CITROEN': { VN: 'G7WFQCUKP5F4OTKAO', PDA: 'G7WFRBR5KDCEC8PC1' },
    'DS':      { VN: 'G7WFS8JIR2OSJSLQ9', PDA: 'G7WFS8JIR2OSJSLQ9' },
    'BAIC':    { VN: 'G7UFEG023OJO3QXVK', PDA: 'G7UFEG023OJO3QXVK' },
  };
  return origins[marca]?.[tipo] || origins[marca]?.VN || null;
};

const determineBusinessTypeId = (marca, tipo) => {
  if (marca === 'BAIC') return tipo === 'PDA' ? 3 : 1;
  if (marca === 'FIAT') return tipo === 'PDA' ? 8 : 7;
  if (marca === 'PEUGEOT') return 3;
  if (marca === 'CITROEN') return tipo === 'PDA' ? 17 : 16;
  if (marca === 'DS') return 18;
  return null;
};

// Si es usado, no importa la marca
if (lead.item_condition === 'used') {
  const asesor = asesores.find(a => a.json.user_id === lead.user_id) || asesores[0];
  if (!asesor?.json?.email) {
    console.warn(`No se encontró asesor para sufijos: ${lead.asesor_phone} / ${lead.asesor_phone2}`);
    return [];
  }
  return {
    json: {
      ...lead,
      pilot_assigned_user: asesor.json.email,
      asesor_nombre_match: asesor.json.nombre,
      asesor_tipo: asesor.json.tipo || 'VN',
      marca_detectada: 'USADOS',
      pilot_origin: 'G84OGKG4B30WJZSW1',
      pilot_business_type_id: 2
    }
  };
}

// Si es nuevo, detecta la marca
const marca = determineMarca(lead);

if (!marca) {
  console.warn(`No se pudo determinar la marca. Título: ${lead.item_titulo}`);
  return [];
}

const esBaicCentral = marca === 'BAIC' && lead.user_id === BAIC_CENTRAL;

if (esBaicCentral && asesorSuite) {
  return {
    json: {
      ...lead,
      pilot_assigned_user: asesorSuite.email.trim().toLowerCase(),
      asesor_nombre_match: `${asesorSuite.first_name || ''} ${asesorSuite.last_name || ''}`.trim(),
      asesor_tipo: 'VN',
      asesor_fuente: 'suite',
      marca_detectada: marca,
      pilot_origin: getOrigin(marca, 'VN'),
      pilot_business_type_id: determineBusinessTypeId(marca, 'VN')
    }
  };
}

// Para BAIC prioriza el asesor de Baic Central, para el resto el del user_id del lead
const asesor = marca === 'BAIC'
  ? (asesores.find(a => a.json.user_id === 2910875794) || asesores.find(a => a.json.user_id === lead.user_id) || asesores[0])
  : (asesores.find(a => a.json.user_id === lead.user_id) || asesores[0]);

if (!asesor?.json?.email) {
  if (esBaicCentral) {
    return {
      json: {
        ...lead,
        pilot_assigned_user: '',
        asesor_nombre_match: '',
        asesor_tipo: 'VN',
        asesor_fuente: 'sin_asignar',
        marca_detectada: marca,
        pilot_origin: getOrigin(marca, 'VN'),
        pilot_business_type_id: determineBusinessTypeId(marca, 'VN'),
        pilot_capture_group: BAIC_CENTRAL_GRUPO_CAPTURA
      }
    };
  }
  console.warn(`No se encontró asesor con email para sufijos: ${lead.asesor_phone} / ${lead.asesor_phone2}`);
  return [];
}

const tipo = asesor.json.tipo || 'VN';
const pilot_origin = getOrigin(marca, tipo);
const pilot_assigned_user = asesor.json.email;
const asesor_nombre = asesor.json.nombre;
const business_type_id = determineBusinessTypeId(marca, tipo);

return {
  json: {
    ...lead,
    pilot_assigned_user,
    asesor_nombre_match: asesor_nombre,
    asesor_tipo: tipo,
    asesor_fuente: 'meli_asesores',
    marca_detectada: marca,
    pilot_origin,
    pilot_business_type_id: business_type_id
  }
};

const pilotResponse = $input.item.json;
const prev = $('PayloadPilot').item.json;
const pilotLeadId = pilotResponse?.data?.welcome_id || null;
const success = pilotResponse.success && !pilotResponse.error && !pilotResponse.message?.toLowerCase().includes('error');

const fullResponse = JSON.stringify(pilotResponse);

return {
  json: {
    lead_id: prev.lead_id,
    pilot_lead_id: pilotLeadId,
    new_status: success ? 'sent' : 'error',
    pilot_response: fullResponse.substring(0, 60000)
  }
};

