const toWA = (raw) => {
  let d = String(raw || '').replace(/\D/g, '').replace(/^00/, '');
  if (!d) return null;
  if (d.startsWith('54')) d = d.slice(2);
  d = d.replace(/^9/, '').replace(/^0/, '');
  return '549' + d;
};

const telefono = toWA(lead.asesor_phone);
const telefonoCliente = toWA(lead.buyer_phone);

return {
  json: {
    telefono,
    contentVariables: JSON.stringify({
      "1": lead.buyer_nombre || "No definido",
      "2": telefonoCliente || "No definido",
      "3": lead.item_titulo || "No definido",
      "4": lead.dealership || "No definida",
      "5": "ML: " + (lead.item_permalink || "")
    })
  }
