];

const resolveModelo = (tituloOriginal) => {
  const tituloLower = (tituloOriginal || '').toLowerCase();
  for (const model of canonicalModels) {
    if (model.keys.some(key => tituloLower.includes(key))) {
      return model.name;
    }
  }
  return (tituloOriginal || '').replace(/\s*asesor\s+.+$/i, '').trim();
};

const name = (lead.buyer_nombre || '').trim();
const cellphone = (lead.buyer_phone || '').replace(/\D/g, '');
const email = lead.buyer_email || '';
const modelo = resolveModelo(lead.item_titulo);
