const contactParams = cellphone
  ? `&pilot_cellphone=${encodeURIComponent(cellphone)}`
  : `&pilot_email=${encodeURIComponent(email)}`;

// Sin asesor (Baic Central): no se manda pilot_assigned_user y el lead queda sin asignar en el grupo de captura
const assignParams = (lead.pilot_assigned_user ? `&pilot_assigned_user=${encodeURIComponent(lead.pilot_assigned_user)}` : '') +
