const lead = $input.item.json;
const normalizarTel = (tel) => {
  if (!tel) return null;
  const digits = tel.toString().replace(/\D/g, '');
  return digits.slice(-8);
};
const normalizarBuyerPhone = (tel) => {
  if (!tel) return null;
  let digits = tel.toString().replace(/\D/g, '');
  if (digits.startsWith('549')) return '+' + digits;
  if (digits.startsWith('54')) return '+549' + digits.slice(2);
  if (digits.startsWith('9') && digits.length >= 10) return '+54' + digits;
  return '+549' + digits;
};
const sufijo1 = normalizarTel(lead.asesor_phone);
const sufijo2 = normalizarTel(lead.asesor_phone2);
return {
  json: {
    ...lead,
    buyer_phone: normalizarBuyerPhone(lead.buyer_phone),
    asesor_sufijo1: sufijo1 || '',
    asesor_sufijo2: sufijo2 || ''
  }
};

const lead = $('Normalizar teléfonos').item.json;
const asesores = $('🗄️ Buscar asesor').all().filter(a => a.json && a.json.email);

const getLast8 = (phone) => (phone || '').toString().replace(/\D/g, '').slice(-8);

const BAIC_CENTRAL = 2910875794;
// Baic Central: asesores del grupo "Ventas ML" (834) de la suite; el cliente lo mantiene ahí.
// Sin asesor -> va sin asignar al grupo de captura de MercadoLibre, para no perder el lead.
const BAIC_CENTRAL_GRUPO_CAPTURA = 'GC - VN BAIC MERCADOLIBRE 3';
const usuariosSuite = (() => {
  try { return $('obtenerAsesoresBaicCentral').first().json?.data?.users || []; }
  catch (e) { return []; }
})();
const sufijos = [lead.asesor_sufijo1, lead.asesor_sufijo2].filter(s => s && s.length === 8);
const asesorSuite = usuariosSuite.find(u => u.status === 'active' && u.email && sufijos.includes(getLast8(u.phone)));

const determineMarca = (lead) => {
  const texto = (lead.item_titulo || '').toLowerCase();
  if (texto.includes('baic') || texto.includes('arcfox')) return 'BAIC';
  if (texto.includes('fiat') || texto.includes('ducato') || texto.includes('cronos') || texto.includes('pulse') || texto.includes('fastback') || texto.includes('toro') || texto.includes('scudo') || texto.includes('mobi') || texto.includes('argo') || texto.includes('fiorino')) return 'FIAT';
  if (texto.includes('peugeot') || texto.includes('3008') || texto.includes('2008') || texto.includes('5008') || texto.includes('308') || texto.includes('408') || texto.includes('208') || texto.includes('partner') || texto.includes('expert') || texto.includes('landtrek')) return 'PEUGEOT';
if (texto.includes('citroen') || texto.includes('citroën') || texto.includes('berlingo') || texto.includes('basalt') || texto.includes('aircross') || texto.includes('c3') || texto.includes('c4') || texto.includes('c5') || texto.includes('jumpy') || texto.includes('jumper') || texto.includes('dispatch') || texto.includes('c-elysee') || texto.includes('spacetourer')) return 'CITROEN';
  if (texto.includes(' ds ') || texto.startsWith('ds ') || texto.includes('ds3') || texto.includes('ds4') || texto.includes('ds7') || texto.includes('ds9')) return 'DS';
  return null;
};

const getOrigin = (marca, tipo) => {
  const origins = {
    'FIAT':    { VN: 'G7UGU65Z3IEOEYC6C', PDA: 'G7UGVHHWLC99QB0Q9' },
    'PEUGEOT': { VN: 'G7WFK23Z7I4SNYZNK', PDA: 'G7WFI1LGYY05VI40C' },
    'CITROEN': { VN: 'G7WFQCUKP5F4OTKAO', PDA: 'G7WFRBR5KDCEC8PC1' },
    'DS':      { VN: 'G7WFS8JIR2OSJSLQ9', PDA: 'G7WFS8JIR2OSJSLQ9' },
    'BAIC':    { VN: 'G7UFEG023OJO3QXVK', PDA: 'G7UFEG023OJO3QXVK' },
  };
  return origins[marca]?.[tipo] || origins[marca]?.VN || null;
};

const determineBusinessTypeId = (marca, tipo) => {
  if (marca === 'BAIC') return tipo === 'PDA' ? 3 : 1;
  if (marca === 'FIAT') return tipo === 'PDA' ? 8 : 7;
  if (marca === 'PEUGEOT') return 3;
  if (marca === 'CITROEN') return tipo === 'PDA' ? 17 : 16;
  if (marca === 'DS') return 18;
  return null;
};

// Si es usado, no importa la marca
if (lead.item_condition === 'used') {
  const asesor = asesores.find(a => a.json.user_id === lead.user_id) || asesores[0];
  if (!asesor?.json?.email) {
    console.warn(`No se encontró asesor para sufijos: ${lead.asesor_phone} / ${lead.asesor_phone2}`);
    return [];
  }
  return {
    json: {
      ...lead,
      pilot_assigned_user: asesor.json.email,
      asesor_nombre_match: asesor.json.nombre,
      asesor_tipo: asesor.json.tipo || 'VN',
      marca_detectada: 'USADOS',
      pilot_origin: 'G84OGKG4B30WJZSW1',
      pilot_business_type_id: 2
    }
  };
}

// Si es nuevo, detecta la marca
const marca = determineMarca(lead);

if (!marca) {
  console.warn(`No se pudo determinar la marca. Título: ${lead.item_titulo}`);
  return [];
}

const esBaicCentral = marca === 'BAIC' && lead.user_id === BAIC_CENTRAL;

if (esBaicCentral && asesorSuite) {
  return {
    json: {
      ...lead,
      pilot_assigned_user: asesorSuite.email.trim().toLowerCase(),
      asesor_nombre_match: `${asesorSuite.first_name || ''} ${asesorSuite.last_name || ''}`.trim(),
      asesor_tipo: 'VN',
      asesor_fuente: 'suite',
      marca_detectada: marca,
      pilot_origin: getOrigin(marca, 'VN'),
      pilot_business_type_id: determineBusinessTypeId(marca, 'VN')
    }
  };
}

// Para BAIC prioriza el asesor de Baic Central, para el resto el del user_id del lead
const asesor = marca === 'BAIC'
  ? (asesores.find(a => a.json.user_id === 2910875794) || asesores.find(a => a.json.user_id === lead.user_id) || asesores[0])
  : (asesores.find(a => a.json.user_id === lead.user_id) || asesores[0]);

if (!asesor?.json?.email) {
  if (esBaicCentral) {
    return {
      json: {
        ...lead,
        pilot_assigned_user: '',
        asesor_nombre_match: '',
        asesor_tipo: 'VN',
        asesor_fuente: 'sin_asignar',
        marca_detectada: marca,
        pilot_origin: getOrigin(marca, 'VN'),
        pilot_business_type_id: determineBusinessTypeId(marca, 'VN'),
        pilot_capture_group: BAIC_CENTRAL_GRUPO_CAPTURA
      }
    };
  }
  console.warn(`No se encontró asesor con email para sufijos: ${lead.asesor_phone} / ${lead.asesor_phone2}`);
  return [];
}

const tipo = asesor.json.tipo || 'VN';
const pilot_origin = getOrigin(marca, tipo);
const pilot_assigned_user = asesor.json.email;
const asesor_nombre = asesor.json.nombre;
const business_type_id = determineBusinessTypeId(marca, tipo);

return {
  json: {
    ...lead,
    pilot_assigned_user,
    asesor_nombre_match: asesor_nombre,
    asesor_tipo: tipo,
    asesor_fuente: 'meli_asesores',
    marca_detectada: marca,
    pilot_origin,
